SndImpl_Update::
	push bc                         ; 407A
	push de                         ; 407B
	call UpdateFade                 ; 407C
	ld hl, wSndFlags                ; 407F
	set 5, [hl]                     ; 4082
	ld hl, wSfxTempoStep            ; 4084
