	sub $4A                         ; 40C0
	ld b, a                         ; 40C2
	ld a, [hl]                      ; 40C3
	sbc a, $00                      ; 40C4
	jr nc, .x40A4                   ; 40C6
.x40C8
	ld hl, wSndFlags                ; 40C8
