	ld hl, wMusTempoStep            ; 40CD
	ld a, [hl+]                     ; 40D0
	add a, [hl]                     ; 40D1
	ld [hl+], a                     ; 40D2
	ld a, $00                       ; 40D3
	adc a, [hl]                     ; 40D5
	ld [hl-], a                     ; 40D6
	ld a, [hl+]                     ; 40D7
	sub $4A                         ; 40D8
	ld b, a                         ; 40DA
	ld a, [hl]                      ; 40DB
	sbc a, $00                      ; 40DC
	jr nc, .x40ED                   ; 40DE
	call IterMusicTracks            ; 40E0
.x40E3
