	call IterTracksNext             ; 4100
	jr nz, .x40FD                   ; 4103
	ld hl, wMusTempoAcc             ; 4105
	ld a, [hl+]                     ; 4108
	sub $4A                         ; 4109
	ld b, a                         ; 410B
	ld a, [hl]                      ; 410C
	sbc a, $00                      ; 410D
	jr nc, .x40ED                   ; 410F
.x4111
	call IterChannels               ; 4111
.x4114
