	call IterChannelsNext           ; 4117
	jr nz, .x4114                   ; 411A
	ld a, [wFrame15]                ; 411C  15-frame counter for the envelope timing correction
	and a                           ; 411F
	jr nz, .x4124                   ; 4120
	ld a, $0F                       ; 4122
.x4124
	dec a                           ; 4124
	ld [wFrame15], a                ; 4125
	ld c, $08                       ; 4128
	ld de, $003C                    ; 412A
	ld hl, wTracks                  ; 412D
.x4130
	ld a, [hl]                      ; 4130
	and $F8                         ; 4131
	ld [hl], a                      ; 4133
	rla                             ; 4134
	rr b                            ; 4135
	add hl, de                      ; 4137
