; de = first SFX track slot, 4 slots
IterSfxTracks:
	ld de, wTracks                  ; 4144
	ld a, $04                       ; 4147
	jr IterTracksSet                ; 4149

; de = first music track slot, 4 slots
IterMusicTracks:
	ld de, wTracks + 4*TRK_SIZE     ; 414B
	ld a, $04                       ; 414E
	jr IterTracksSet                ; 4150
.x4152
	ld de, wTracks                  ; 4152  never called
	ld a, $08                       ; 4155
IterTracksSet:
	ld hl, wIterCount               ; 4157
	ld [hl+], a                     ; 415A
	ld a, e                         ; 415B
	ld [hl+], a                     ; 415C
	ld [hl], d                      ; 415D
	ret                             ; 415E

; advance wCurTrack by TRK_SIZE; z = done
IterTracksNext:
	ld hl, wIterCount               ; 415F
	dec [hl]                        ; 4162
	ret z                           ; 4163
	inc hl                          ; 4164
	ld a, $3C                       ; 4165
	add a, [hl]                     ; 4167
	ld [hl+], a                     ; 4168
	ld a, $00                       ; 4169
	adc a, [hl]                     ; 416B
	ld [hl], a                      ; 416C
	rra                             ; 416D
	ret                             ; 416E
SelectChannel1:
	ld de, wChannels                ; 416F
	ld a, $01                       ; 4172
	ld c, $12                       ; 4174
	jr IterChannelsSet              ; 4176
SelectChannel2:
	ld de, wChannels + 1*CH_SIZE    ; 4178
	ld a, $01                       ; 417B
	ld c, $17                       ; 417D
	jr IterChannelsSet              ; 417F
SelectChannel3:
	ld de, wChannels + 2*CH_SIZE    ; 4181
	ld a, $01                       ; 4184
	ld c, $1C                       ; 4186
	jr IterChannelsSet              ; 4188
SelectChannel4:
	ld de, wChannels + 3*CH_SIZE    ; 418A
	ld a, $01                       ; 418D
	ld c, $21                       ; 418F
	jr IterChannelsSet              ; 4191

; all 4 hardware channels
IterChannels:
	ld de, wChannels                ; 4193
	ld a, $04                       ; 4196
	ld c, $12                       ; 4198
IterChannelsSet:
	ld hl, wChanIterCount           ; 419A
	ld [hl+], a                     ; 419D
	ld a, e                         ; 419E
	ld [hl+], a                     ; 419F
	ld a, d                         ; 41A0
	ld [hl+], a                     ; 41A1
	ld [hl], c                      ; 41A2
	ret                             ; 41A3

; advance wCurChan / wCurChanReg; z = done
IterChannelsNext:
	ld hl, wChanIterCount           ; 41A4
	dec [hl]                        ; 41A7
	ret z                           ; 41A8
	inc hl                          ; 41A9
	ld a, $18                       ; 41AA
	add a, [hl]                     ; 41AC
	ld [hl+], a                     ; 41AD
	ld a, $00                       ; 41AE
	adc a, [hl]                     ; 41B0
	ld [hl+], a                     ; 41B1
	ld a, [hl]                      ; 41B2
	add a, $05                      ; 41B3
	ld [hl], a                      ; 41B5
	rra                             ; 41B6
	ret                             ; 41B7

; API $3F0C: start sound bc in the SFX track slots (bc = 0: stop all SFX)
; (called through Sound_PlaySfx)
SndImpl_PlaySfx::
	ld a, b                         ; 41B8
	or c                            ; 41B9
	jp z, StopAllSfx                ; 41BA
	call LookupSound                ; 41BD
	ld a, [wSndSlot]                ; 41C0
	bit 7, a                        ; 41C3
	jr nz, PlaySfx_AutoSlot         ; 41C5
	ld b, a                         ; 41C7
	sub $04                         ; 41C8
	jr nc, .x420E                   ; 41CA
	cpl                             ; 41CC
	inc a                           ; 41CD
	ld [wIterCount], a              ; 41CE
	ld hl, wTracks                  ; 41D1
	ld a, b                         ; 41D4
	and a                           ; 41D5
	jr z, .x41DF                    ; 41D6
	ld de, $003C                    ; 41D8
.x41DB
	add hl, de                      ; 41DB
	dec b                           ; 41DC
	jr nz, .x41DB                   ; 41DD
.x41DF
	ld a, l                         ; 41DF
	ld [wCurTrack], a               ; 41E0
	ld a, h                         ; 41E3
	ld [wCurTrack+1], a             ; 41E4
	jr .x41F1                       ; 41E7
.x41E9
	ld a, [wCurTrack]               ; 41E9
	ld l, a                         ; 41EC
	ld a, [wCurTrack+1]             ; 41ED
	ld h, a                         ; 41F0
.x41F1
	bit 7, [hl]                     ; 41F1
	jr z, .x4204                    ; 41F3
	ld bc, TRK_PRIO                 ; 41F5
	add hl, bc                      ; 41F8
	ld a, [wSndPrio]                ; 41F9
	cp [hl]                         ; 41FC
	jr nc, .x4204                   ; 41FD
	call NextHeaderTrack            ; 41FF
	jr .x4207                       ; 4202
.x4204
