	call InitTrackSlot              ; 4229
	jr z, .x427C                    ; 422C
	ld a, [wSndArgD]                ; 422E
	ld b, a                         ; 4231
	ld a, [wSndArgC]                ; 4232
	or b                            ; 4235
	ld [wSndArgC], a                ; 4236
.x4239
	ld a, [wSndArgD]                ; 4239
	sla a                           ; 423C
	ld [wSndArgD], a                ; 423E
	call IterTracksNext             ; 4241
	jr nz, .x421D                   ; 4244
	call IterSfxTracks              ; 4246
	ld a, $01                       ; 4249
	ld [wSndArgD], a                ; 424B
.x424E
	ld a, [wSndArgD]                ; 424E
	ld b, a                         ; 4251
	ld a, [wSndArgC]                ; 4252
	and b                           ; 4255
	jr nz, .x426F                   ; 4256
	ld a, [wCurTrack]               ; 4258
	ld l, a                         ; 425B
	ld a, [wCurTrack+1]             ; 425C
	ld h, a                         ; 425F
	ld bc, TRK_PRIO                 ; 4260
