; API $3F12: start sound bc in the music track slots (bc = 0: pause music)
; (called through Sound_PlayMusic)
SndImpl_PlayMusic::
	ld a, b                         ; 427F
	or c                            ; 4280
	jp z, SndImpl_StopMusic         ; 4281
	ld a, c                         ; 4284
	ld [wMusicId], a                ; 4285
	ld a, b                         ; 4288
	ld [wMusicId+1], a              ; 4289
	xor a                           ; 428C
	ld [wFadeSpeed], a              ; 428D
	xor a                           ; 4290
	ld [wMusicPaused], a            ; 4291
	call LookupSound                ; 4294
	call IterMusicTracks            ; 4297
.x429A
	call InitTrackSlot              ; 429A
	jr z, .x42B0                    ; 429D
	call IterTracksNext             ; 429F
	jr nz, .x429A                   ; 42A2
	jr .x42B5                       ; 42A4
.x42A6
	ld a, [wCurTrack]               ; 42A6
	ld l, a                         ; 42A9
	ld a, [wCurTrack+1]             ; 42AA
	ld h, a                         ; 42AD
	xor a                           ; 42AE
