; API $3F18: play unless bc is already the playing music
; (called through Sound_PlayMusicIfNew)
SndImpl_PlayMusicIfNew::
	ld a, [wMusicId]                ; 42B8
	cp c                            ; 42BB
	jr nz, SndImpl_PlayMusic        ; 42BC
	ld a, [wMusicId+1]              ; 42BE
	cp b                            ; 42C1
	jr nz, SndImpl_PlayMusic        ; 42C2
	ld a, [wActiveMask]             ; 42C4
	and $F0                         ; 42C7
	jr z, SndImpl_PlayMusic         ; 42C9
	jp Snd_Exit                     ; 42CB

; API $3F48: play if new, resume if it is the current (paused) music
; (called through Sound_PlayOrResume)
SndImpl_PlayOrResume::
	ld a, [wMusicId]                ; 42CE
	cp c                            ; 42D1
	jr nz, SndImpl_PlayMusic        ; 42D2
	ld a, [wMusicId+1]              ; 42D4
	cp b                            ; 42D7
	jr nz, SndImpl_PlayMusic        ; 42D8
	ld a, [wActiveMask]             ; 42DA
	and $F0                         ; 42DD
	jr z, SndImpl_ResumeMusic       ; 42DF
	jp Snd_Exit                     ; 42E1

; API $3F2A: reactivate paused music tracks
; (called through Sound_ResumeMusic)
SndImpl_ResumeMusic::
	xor a                           ; 42E4
	ld [wMusicPaused], a            ; 42E5
	call IterMusicTracks            ; 42E8
.x42EB
	ld a, [wCurTrack]               ; 42EB
	ld l, a                         ; 42EE
	ld a, [wCurTrack+1]             ; 42EF
	ld h, a                         ; 42F2
	ld a, [hl]                      ; 42F3
	and $60                         ; 42F4
	jr z, .x42FA                    ; 42F6
	set 7, [hl]                     ; 42F8
.x42FA
	call IterTracksNext             ; 42FA
	jr nz, .x42EB                   ; 42FD
	jp Snd_Exit                     ; 42FF

; bc = id -> wSndPtr/wSndBank/wSndPrio/wSndSlot/wSndArgE (track count); bad id: abort the API call
LookupSound:
	ld a, b                         ; 4302
	ld [wSndArgB], a                ; 4303
	cp $02                          ; 4306  ids $000-$238 only
	ld a, c                         ; 4308
	jr z, .x4311                    ; 4309
	jr c, .x4315                    ; 430B
.x430D
	pop hl                          ; 430D
	jp Snd_Exit                     ; 430E
.x4311
	cp $39                          ; 4311
	jr nc, .x430D                   ; 4313
.x4315
	ld [wSndArgA], a                ; 4315
	ld l, c                         ; 4318
	ld h, b                         ; 4319
	add hl, hl                      ; 431A
	add hl, hl                      ; 431B
	add hl, hl                      ; 431C
	ld bc, SoundTable               ; 431D
