	ld hl, $0006                    ; 43E6
	add hl, bc                      ; 43E9
	ld a, [wSndArgA]                ; 43EA
	cp [hl]                         ; 43ED
	jr nz, .x43F9                   ; 43EE
	inc hl                          ; 43F0
	ld a, [wSndArgB]                ; 43F1
	cp [hl]                         ; 43F4
	jr nz, .x43F9                   ; 43F5
	xor a                           ; 43F7
	ld [bc], a                      ; 43F8
.x43F9
	call IterTracksNext             ; 43F9
	jr nz, .x43D9                   ; 43FC
	jp Snd_Exit                     ; 43FE
StopAllSfx:
