.x4404
	ld a, [wCurTrack]               ; 4404
	ld l, a                         ; 4407
	ld a, [wCurTrack+1]             ; 4408
	ld h, a                         ; 440B
	xor a                           ; 440C
	ld [hl], a                      ; 440D
	call IterTracksNext             ; 440E
	jr nz, .x4404                   ; 4411
