; API $3F24: pause the music tracks (they can be resumed)
; (called through Sound_StopMusic)
SndImpl_StopMusic::
	call PauseMusicTracks           ; 4416
	jp Snd_Exit                     ; 4419
FadeDone:
	xor a                           ; 441C
	ld [wFadeSpeed], a              ; 441D
PauseMusicTracks:
	ld a, $FF                       ; 4420
