.x4428
	ld a, [wCurTrack]               ; 4428
	ld l, a                         ; 442B
	ld a, [wCurTrack+1]             ; 442C
	ld h, a                         ; 442F
	res 7, [hl]                     ; 4430
	call IterTracksNext             ; 4432
	jr nz, .x4428                   ; 4435
	ret                             ; 4437

; API $3F30: d = active SFX slot mask, e = active music slot mask
; (called through Sound_GetActive)
SndImpl_GetActive::
	ld a, [wActiveMask]             ; 4438
	and $0F                         ; 443B
	ld d, a                         ; 443D
	ld a, [wActiveMask]             ; 443E
	and $F0                         ; 4441
	swap a                          ; 4443
	ld e, a                         ; 4445
	jp Snd_Exit                     ; 4446

; API $3F42: a = 0: bc = current music id (0 if none active); a = 1-4: bc = id in SFX slot a
; (called through Sound_Query)
SndImpl_Query::
	and a                           ; 4449
	jr nz, .x445D                   ; 444A
	ld a, [wActiveMask]             ; 444C
	and $F0                         ; 444F
	jr z, .x4461                    ; 4451
	ld a, [wMusicId]                ; 4453
	ld c, a                         ; 4456
	ld a, [wMusicId+1]              ; 4457
	ld b, a                         ; 445A
	jr .x4485                       ; 445B
.x445D
	cp $05                          ; 445D
	jr c, .x4466                    ; 445F
.x4461
	ld bc, $0000                    ; 4461
	jr .x4485                       ; 4464
.x4466
	ld bc, SfxSlotPtrs - 2          ; 4466
	sla a                           ; 4469
	add a, c                        ; 446B
	ld c, a                         ; 446C
	ld a, $00                       ; 446D
	adc a, b                        ; 446F
	ld b, a                         ; 4470
	ld a, [bc]                      ; 4471
	ld l, a                         ; 4472
	inc bc                          ; 4473
	ld a, [bc]                      ; 4474
	ld h, a                         ; 4475
	ld bc, $0000                    ; 4476
	bit 7, [hl]                     ; 4479
	jr z, .x4485                    ; 447B
	ld bc, $0006                    ; 447D
	add hl, bc                      ; 4480
	ld a, [hl+]                     ; 4481
	ld c, a                         ; 4482
	ld a, [hl+]                     ; 4483
	ld b, a                         ; 4484
.x4485
	jp Snd_Exit                     ; 4485

SfxSlotPtrs:
	dw wTracks
	dw wTracks + 1*TRK_SIZE
	dw wTracks + 2*TRK_SIZE
	dw wTracks + 3*TRK_SIZE

ParamTable:
	dw Param_TempoScale
	dw Param_PitchOffset
	dw Param_VolumeScale
	dw Param_PanOffset
	dw Param_LfoDepth
	dw Param_LfoSpeed
