; API $3F36: a = parameter 0-6, bc = value, d/e = SFX/music track masks
; (called through Sound_SetParam)
SndImpl_SetParam::
	call SetParam                   ; 449E
	jp Snd_Exit                     ; 44A1
SetParam:
	cp $07                          ; 44A4
	ret nc                          ; 44A6
	push af                         ; 44A7
	ld hl, wSndArgA                 ; 44A8
	ld a, c                         ; 44AB
	ld [hl+], a                     ; 44AC
	ld a, b                         ; 44AD
	ld [hl+], a                     ; 44AE
	ld a, e                         ; 44AF
	ld [hl+], a                     ; 44B0
	ld a, d                         ; 44B1
	ld [hl+], a                     ; 44B2
	xor a                           ; 44B3
	ld [hl], a                      ; 44B4
	pop af                          ; 44B5
	ld bc, ParamTable               ; 44B6
	jp JumpTable                    ; 44B9

; for each selected track: TRK+bc = wSndArgB, flags |= wSndArgE
SetTrackByte:
	call GetParamMask               ; 44BC
.x44BF
	rrc d                           ; 44BF
	jr nc, .x44D3                   ; 44C1
	bit 7, [hl]                     ; 44C3
	jr z, .x44D3                    ; 44C5
	ld a, [wSndArgE]                ; 44C7
	or [hl]                         ; 44CA
	ld [hl], a                      ; 44CB
	push hl                         ; 44CC
	add hl, bc                      ; 44CD
	ld a, [wSndArgB]                ; 44CE
	ld [hl], a                      ; 44D1
	pop hl                          ; 44D2
.x44D3
	call NextParamTrack             ; 44D3
	jr nz, .x44BF                   ; 44D6
	ret                             ; 44D8

; for each selected track: TRK+bc = wSndArgA/wSndArgB, flags |= wSndArgE
SetTrackWord:
	call GetParamMask               ; 44D9
.x44DC
	rrc d                           ; 44DC
	jr nc, .x44F4                   ; 44DE
	bit 7, [hl]                     ; 44E0
	jr z, .x44F4                    ; 44E2
	ld a, [wSndArgE]                ; 44E4
	or [hl]                         ; 44E7
	ld [hl], a                      ; 44E8
	push hl                         ; 44E9
	add hl, bc                      ; 44EA
	ld a, [wSndArgA]                ; 44EB
	ld [hl+], a                     ; 44EE
	ld a, [wSndArgB]                ; 44EF
	ld [hl-], a                     ; 44F2
	pop hl                          ; 44F3
.x44F4
	call NextParamTrack             ; 44F4
	jr nz, .x44DC                   ; 44F7
	ret                             ; 44F9

; d = music mask << 4 | SFX mask, e = 8, hl = first track
GetParamMask:
	ld a, [wSndArgD]                ; 44FA
	and $0F                         ; 44FD
	ld d, a                         ; 44FF
	ld a, [wSndArgC]                ; 4500
	swap a                          ; 4503
	and $F0                         ; 4505
	or d                            ; 4507
	ld d, a                         ; 4508
	ld e, $08                       ; 4509
	ld hl, wTracks                  ; 450B
	ret                             ; 450E
NextParamTrack:
	ld a, $3C                       ; 450F
	add a, l                        ; 4511
	ld l, a                         ; 4512
	ld a, $00                       ; 4513
	adc a, h                        ; 4515
	ld h, a                         ; 4516
	dec e                           ; 4517
	ret                             ; 4518

; API $3F3C: a = frames per step, music volume scale $40 -> 0 in steps of 4
; (called through Sound_FadeOut)
SndImpl_FadeOut::
	ld [wFadeSpeed], a              ; 4519
	ld [wFadeTimer], a              ; 451C
	ld a, $40                       ; 451F
