UpdateFade:
	ld a, [wMusicPaused]            ; 4527
	and a                           ; 452A
	ret nz                          ; 452B  fixed from Wario Land II: fade only while the music plays
	ld a, [wFadeSpeed]              ; 452C
	and a                           ; 452F
	ret z                           ; 4530
	ld hl, wFadeTimer               ; 4531
	dec [hl]                        ; 4534
	ret nz                          ; 4535
	ld [hl+], a                     ; 4536
	ld a, [hl]                      ; 4537
	sub $04                         ; 4538
