.x456F
	ld [wTrackFlags], a             ; 456F
	inc hl                          ; 4572
	ld a, [hl]                      ; 4573
	and a                           ; 4574
	jr z, .x457B                    ; 4575
	dec [hl]                        ; 4577
	inc hl                          ; 4578
	jr TrackLfo                     ; 4579
.x457B
	inc hl                          ; 457B
	ld a, [hl+]                     ; 457C
	ld e, a                         ; 457D
	ld a, [hl+]                     ; 457E
	ld d, a                         ; 457F
