; jump to table bc entry a
JumpTable:
	sla a                           ; 45B6
	add a, c                        ; 45B8
	ld c, a                         ; 45B9
	ld a, $00                       ; 45BA
	adc a, b                        ; 45BC
	ld b, a                         ; 45BD
