	ld bc, $0029                    ; 45CF
	add hl, bc                      ; 45D2
	ld a, [hl]                      ; 45D3
	and a                           ; 45D4
	jr z, .x45E0                    ; 45D5
	dec [hl]                        ; 45D7
	ld bc, $FFF5                    ; 45D8
	add hl, bc                      ; 45DB
	ld a, $40                       ; 45DC
	jr .x45E6                       ; 45DE
.x45E0
	ld bc, $FFF4                    ; 45E0
	add hl, bc                      ; 45E3
	ld a, [hl+]                     ; 45E4
	add a, [hl]                     ; 45E5
.x45E6
	ld [hl], a                      ; 45E6
