	ld a, [hl+]                     ; 45F3
	add a, [hl]                     ; 45F4
	jr z, .x460C                    ; 45F5
	ld c, a                         ; 45F7
	ld a, [wLfoValue]               ; 45F8
	ld b, a                         ; 45FB
	push hl                         ; 45FC
	push bc                         ; 45FD
	call Mul8                       ; 45FE
	pop bc                          ; 4601
	ld b, h                         ; 4602
	pop hl                          ; 4603
	inc hl                          ; 4604
	ld a, [hl+]                     ; 4605
	cp $00                          ; 4606
	jr z, .x4617                    ; 4608
	jr .x4646                       ; 460A
.x460C
	ld bc, $0000                    ; 460C
	inc hl                          ; 460F
	ld a, [hl+]                     ; 4610
	cp $00                          ; 4611
	jr z, .x4629                    ; 4613
	jr .x4646                       ; 4615
.x4617
	ld a, b                         ; 4617
	srl c                           ; 4618
	sub c                           ; 461A
	ld c, a                         ; 461B
	ld a, $00                       ; 461C
	sbc a, a                        ; 461E
	sla c                           ; 461F
	rla                             ; 4621
	sla c                           ; 4622
	rla                             ; 4624
	sla c                           ; 4625
	rla                             ; 4627
	ld b, a                         ; 4628
.x4629
	ld a, c                         ; 4629
	cp [hl]                         ; 462A
	jr z, .x4636                    ; 462B
	ld a, [wTrackFlags]             ; 462D
	set 2, a                        ; 4630
	ld [wTrackFlags], a             ; 4632
	ld [hl], c                      ; 4635
.x4636
	inc hl                          ; 4636
	ld a, b                         ; 4637
	cp [hl]                         ; 4638
	jr z, .x4644                    ; 4639
	ld a, [wTrackFlags]             ; 463B
	set 2, a                        ; 463E
	ld [wTrackFlags], a             ; 4640
	ld [hl], b                      ; 4643
.x4644
	jr .x4646                       ; 4644
.x4646
	ld a, [wCurTrack]               ; 4646
