ApplyTrackParams:
	bit 2, a                        ; 4651
	jr z, .x4691                    ; 4653
	ld bc, $001D                    ; 4655
	add hl, bc                      ; 4658
	ld e, [hl]                      ; 4659
	ld a, $00                       ; 465A
	sla e                           ; 465C
	sbc a, a                        ; 465E
	ld d, a                         ; 465F
	ld bc, $FFFE                    ; 4660
	add hl, bc                      ; 4663
	ld a, [hl+]                     ; 4664
	add a, e                        ; 4665
	ld e, a                         ; 4666
	ld a, [hl-]                     ; 4667
	adc a, d                        ; 4668
	ld d, a                         ; 4669
	ld bc, $FFF8                    ; 466A
	add hl, bc                      ; 466D
	ld a, [hl+]                     ; 466E
	add a, e                        ; 466F
	ld e, a                         ; 4670
	ld a, [hl-]                     ; 4671
	adc a, d                        ; 4672
	ld d, a                         ; 4673
	ld bc, $0010                    ; 4674
	add hl, bc                      ; 4677
	ld a, [hl+]                     ; 4678
	cp $00                          ; 4679
	jr nz, .x4683                   ; 467B
	ld a, [hl+]                     ; 467D
	add a, e                        ; 467E
	ld e, a                         ; 467F
	ld a, [hl-]                     ; 4680
	adc a, d                        ; 4681
	ld d, a                         ; 4682
.x4683
	ld bc, $0008                    ; 4683
	add hl, bc                      ; 4686
	ld a, e                         ; 4687
	ld [hl+], a                     ; 4688
	ld [hl], d                      ; 4689
	ld bc, $FFD3                    ; 468A
	add hl, bc                      ; 468D
	ld a, [wTrackFlags]             ; 468E
.x4691
	bit 0, a                        ; 4691
	jr z, .x46A8                    ; 4693
	ld bc, $0017                    ; 4695
	add hl, bc                      ; 4698
	ld a, [hl+]                     ; 4699
	add a, [hl]                     ; 469A
	ld e, a                         ; 469B
	ld bc, $0016                    ; 469C
	add hl, bc                      ; 469F
	ld [hl], e                      ; 46A0
	ld bc, $FFD2                    ; 46A1
	add hl, bc                      ; 46A4
	ld a, [wTrackFlags]             ; 46A5
.x46A8
	bit 1, a                        ; 46A8
	jr z, .x46CF                    ; 46AA
	ld bc, $0015                    ; 46AC
	add hl, bc                      ; 46AF
