.x46C0
	rlca                            ; 46C0
	rlca                            ; 46C1
	ld e, a                         ; 46C2
	ld bc, $0019                    ; 46C3
	add hl, bc                      ; 46C6
	ld [hl], e                      ; 46C7
	ld bc, $FFD1                    ; 46C8
