; $CD sub, value: instrument / envelope / echo overrides
Cmd_Ext:
	ld a, [wCmdParam]               ; 4727
	inc de                          ; 472A
	cp $0C                          ; 472B
	jp nc, Cmd_End                  ; 472D
	ld b, a                         ; 4730
	call Snd_ReadByte               ; 4731
	ld a, c                         ; 4734
	ld [wCmdParam], a               ; 4735
	ld a, b                         ; 4738
