; $80-$B0: rest LengthTable[cmd - $80] ticks
Cmd_Wait:
	add a, $31                      ; 473F
	jp z, ReadCommand               ; 4741
	add a, LOW(LengthTable)         ; 4744
	ld l, a                         ; 4746
	ld a, $00                       ; 4747
