	ld h, a                         ; 474B
	ld b, [hl]                      ; 474C
	dec b                           ; 474D
	ld a, [wCurTrack]               ; 474E
	ld l, a                         ; 4751
	ld a, [wCurTrack+1]             ; 4752
	ld h, a                         ; 4755
	inc hl                          ; 4756
	ld a, b                         ; 4757
	ld [hl+], a                     ; 4758
	ld a, e                         ; 4759
	ld [hl+], a                     ; 475A
	ld a, d                         ; 475B
	ld [hl-], a                     ; 475C
