; $B3 addr
Cmd_Call:
	ld a, [wCurTrack]               ; 4760
	ld l, a                         ; 4763
	ld a, [wCurTrack+1]             ; 4764
	ld h, a                         ; 4767
	ld bc, TRK_SP                   ; 4768
	add hl, bc                      ; 476B
	ld a, [hl]                      ; 476C
	cp $0A                          ; 476D
	jp nc, Cmd_End                  ; 476F
	inc a                           ; 4772
	inc a                           ; 4773
	ld [hl], a                      ; 4774
	ld c, a                         ; 4775
	ld b, $00                       ; 4776
	add hl, bc                      ; 4778
	ld bc, $000A                    ; 4779
	add hl, bc                      ; 477C
	inc de                          ; 477D
	inc de                          ; 477E
	ld a, e                         ; 477F
	ld [hl+], a                     ; 4780
	ld [hl], d                      ; 4781
	dec de                          ; 4782
	dec de                          ; 4783

; $B2 addr
Cmd_Jump:
	call Snd_ReadWord               ; 4784
	ld e, c                         ; 4787
