; $B4 (no-op when nothing was called)
Cmd_Ret:
	ld a, [wCurTrack]               ; 478C
	ld l, a                         ; 478F
	ld a, [wCurTrack+1]             ; 4790
	ld h, a                         ; 4793
	ld bc, TRK_SP                   ; 4794
	add hl, bc                      ; 4797
	ld a, [hl]                      ; 4798
	and a                           ; 4799
	jp z, ReadCommand               ; 479A
	dec a                           ; 479D
	dec a                           ; 479E
	ld [hl], a                      ; 479F
	ld c, a                         ; 47A0
	ld b, $00                       ; 47A1
	add hl, bc                      ; 47A3
	ld bc, $000C                    ; 47A4
	add hl, bc                      ; 47A7
	ld a, [hl+]                     ; 47A8
	ld e, a                         ; 47A9
	ld d, [hl]                      ; 47AA
	jp ReadCommand                  ; 47AB

; $B5 count, addr (count 0 = jump)
Cmd_Loop:
	ld a, [wCurTrack]               ; 47AE
	ld l, a                         ; 47B1
	ld a, [wCurTrack+1]             ; 47B2
	ld h, a                         ; 47B5
	ld bc, TRK_LOOPCOUNT            ; 47B6
	add hl, bc                      ; 47B9
	ld a, [wCmdParam]               ; 47BA
	inc de                          ; 47BD
	and a                           ; 47BE
	jr z, Cmd_Jump                  ; 47BF
	inc [hl]                        ; 47C1
	cp [hl]                         ; 47C2
	jr nz, Cmd_Jump                 ; 47C3
	xor a                           ; 47C5
	ld [hl], a                      ; 47C6
	inc de                          ; 47C7
	inc de                          ; 47C8
	jp ReadCommand                  ; 47C9

; $BC n: tempo of this track's group
Cmd_Tempo:
	ld hl, wSndFlags                ; 47CC
	bit 5, [hl]                     ; 47CF
	ld hl, wMusTempo                ; 47D1
	jr z, .x47D9                    ; 47D4
	ld hl, wSfxTempo                ; 47D6
.x47D9
