	ld [hl], a                      ; 47DD
	call CalcTempoStep              ; 47DE
	jp ReadCommand                  ; 47E1

; step = tempo * scale / 64, at least 1, at most $FF
CalcTempoStep:
	ld a, [hl+]                     ; 47E4
	ld b, a                         ; 47E5
	ld a, [hl+]                     ; 47E6
	ld c, a                         ; 47E7
	push hl                         ; 47E8
	call Mul8                       ; 47E9
