	ld [wTrackFlags], a             ; 4C57
	call CalcPeakLevel              ; 4C5A
	ld bc, $000B                    ; 4C5D
	add hl, bc                      ; 4C60
	ld a, [hl]                      ; 4C61
	ld bc, $0006                    ; 4C62
	add hl, bc                      ; 4C65
	swap a                          ; 4C66
